(function() {
    const container = document.getElementById('related-posts-container');
    if (!container) return;

    const MAX_POSTS = 6;
    let currentPostUrl = '';
    const uniquePosts = new Map(); // Para armazenar posts únicos por URL

    // Função para obter a URL canônica do post atual
    function getCurrentPostUrl() {
        const canonicalLink = document.querySelector('link[rel="canonical"]');
        return canonicalLink ? canonicalLink.href : window.location.href;
    }

    // Função para obter os labels do post atual
    function getLabels() {
        const metaTags = document.querySelectorAll('meta[property="article:tag"]');
        if (metaTags.length > 0) {
            return Array.from(metaTags).map(tag => tag.content);
        }
        const labelElements = document.querySelectorAll('.post-labels a'); // Fallback para elementos comuns do Blogger
        if (labelElements.length > 0) {
            return Array.from(labelElements).map(el => el.textContent.trim());
        }
        return [];
    }

    // Função para construir a URL do feed JSON do Blogger
    function buildFeedUrl(label = '') {
        const blogUrl = window.location.origin;
        const labelSegment = label ? `/-/` + encodeURIComponent(label) : '';
        // Busca o dobro de posts para ter margem para filtrar o post atual e duplicatas
        return `${blogUrl}/feeds/posts/summary${labelSegment}?alt=json-in-script&max-results=${MAX_POSTS * 2}&callback=relatedPostsCallback`;
    }

    // Renderiza o skeleton placeholder
    function renderSkeleton() {
        let skeletonHtml = '<div class="row g-3">';
        for (let i = 0; i < MAX_POSTS; i++) {
            skeletonHtml += `
                <div class="col-12 col-md-6 col-lg-4">
                    <div class="card sl-card-bg shadow-sm h-100 border-0">
                        <div class="ratio ratio-16x9 bg-light rounded-top"></div>
                        <div class="card-body">
                            <h5 class="card-title placeholder-glow">
                                <span class="placeholder col-8"></span>
                            </h5>
                            <p class="card-text placeholder-glow">
                                <span class="placeholder col-6"></span>
                                <span class="placeholder col-4"></span>
                                <span class="placeholder col-7"></span>
                            </p>
                        </div>
                    </div>
                </div>`;
        }
        skeletonHtml += '</div>';
        container.innerHTML = skeletonHtml;
    }

    // Renderiza os posts reais
    function renderPosts(posts) {
        if (posts.length === 0) {
            renderFallback('Nenhum post relacionado encontrado.');
            return;
        }

        let postsHtml = '<div class="row g-3">';
        posts.forEach(post => {
            postsHtml += `
                <div class="col-12 col-md-6 col-lg-4">
                    <div class="card sl-card-bg shadow-sm h-100 border-0">
                        <div class="ratio ratio-16x9">
                            <img src="${post.thumbnail}" class="card-img-top object-fit-cover" alt="${post.title}">
                        </div>
                        <div class="card-body">
                            <h5 class="card-title mb-2"><a href="${post.url}" class="text-decoration-none text-sl-text-main">${post.title}</a></h5>
                            <p class="card-text text-muted small">${post.summary.substring(0, 100)}...</p>
                        </div>
                    </div>
                </div>`;
        });
        postsHtml += '</div>';
        container.innerHTML = postsHtml;
    }

    // Renderiza mensagem de fallback/erro
    function renderFallback(message) {
        container.innerHTML = `<div class="alert alert-info" role="alert">${message}</div>`;
    }

    // Callback global para o JSON-in-script do Blogger
    window.relatedPostsCallback = function(json) {
        const entries = json.feed.entry || [];
        entries.forEach(entry => {
            const postUrl = entry.link.find(l => l.rel === 'alternate' && l.type === 'text/html')?.href;
            if (postUrl && postUrl !== currentPostUrl && !uniquePosts.has(postUrl)) {
                uniquePosts.set(postUrl, {
                    title: entry.title.$t,
                    url: postUrl,
                    thumbnail: entry.media$thumbnail?.url.replace('/s72-c/', '/w720-h405-c/') || 'https://via.placeholder.com/720x405/dee2e6/6c757d?text=No+Image',
                    summary: entry.summary.$t.replace(/<[^>]*>?/gm, ''), // Remove HTML da descrição
                    published: entry.published.$t,
                    author: entry.author[0]?.name.$t
                });
            }
        });

        // Converte o Map para Array, ordena por data de publicação (desc) e pega o número máximo de posts
        const finalPosts = Array.from(uniquePosts.values())
            .sort((a, b) => new Date(b.published) - new Date(a.published))
            .slice(0, MAX_POSTS);

        renderPosts(finalPosts);
    };

    // Execução principal
    currentPostUrl = getCurrentPostUrl();
    renderSkeleton();

    const labels = getLabels();
    // Usa o primeiro label encontrado ou um feed geral se nenhum label for encontrado
    const feedUrl = labels.length > 0 ? buildFeedUrl(labels[0]) : buildFeedUrl();

    // Carrega o script do feed JSON
    const script = document.createElement('script');
    script.src = feedUrl;
    script.async = true;
    script.onerror = () => {
        renderFallback('Ocorreu um erro ao carregar os posts relacionados.');
    };
    document.head.appendChild(script);

})();

